include <robotics.scad>
// ROBOTIS RH-P12-RN housing + 42x42 base boss. Origin: boss underside centre, front = -Y.
$fn = 40;
D  = 54;      // housing depth (drawing)
zb = 9.2;     // boss height / housing underside (scaled from drawing)
zt = 58.4;    // housing top (scaled)
ch = 1.2;     // edge break (not dimensioned)
// front-view profile (scaled from drawing, X +-40.25 = 80.5 wide)
prof = [[-24,zb],[24,zb],[40.25,20.3],[40.25,zt],[-40.25,zt],[-40.25,20.3]];
module prof2(o=0) offset(delta=o) offset(r=8) offset(delta=-8) polygon(prof);
module xz(h) rotate([90,0,0]) linear_extrude(h, center=true) children();
module inner_link2(o=0) offset(delta=o) hull(){ translate([57.7,76.6]) circle(3.5); translate([33.8,64.4]) circle(3.5); }
module outer_link2(o=0) offset(delta=o) hull(){ translate([68.1,65.6]) circle(4.5); translate([42.8,23.2]) circle(4.5); }
module both() { children(); mirror([1,0,0]) children(); }

module body() hull(){ xz(D-2*ch) prof2(); xz(D) prof2(-ch); }
module boss() cuboid([42,42,zb+1], rounding=3, edges="Z", anchor=BOT);
module ears() both() xz(30) hull(){ translate([28.5,zt-1]) square([10.5,1]); translate([33.8,64.4]) circle(5); }

difference(){
  union(){ body(); boss(); ears(); }
  // clevis slots for the finger links (plain clearance)
  both() { xz(16.6) inner_link2(0.4); xz(16.6) outer_link2(0.4); }
  // 12x M3 tap (tap drill 2.5, 6 deep) on boss +-X faces, 3 mm above underside
  for (sx=[-1,1], y=[-18,-12,-6,6,12,18]) translate([sx*21,y,3]) rotate([0,90,0]) cylinder(d=2.5, h=12, center=true);
  // 8x M3 tap on front/back faces: upper pair 24 apart, lower pair 32 apart, 42 vertical
  for (sy=[-1,1], p=[[-12,55.4],[12,55.4],[-16,13.4],[16,13.4]]) translate([p[0],sy*27,p[1]]) rotate([90,0,0]) cylinder(d=2.5, h=12, center=true);
  // 2x M2.5 tap on top, 22 apart
  for (y=[-11,11]) translate([0,y,zt-5]) cylinder(d=2.05, h=10);
  // connector pockets on underside behind boss, sized to the connector bodies (line-to-line)
  for (x=[-6.4,6.4]) translate([x,23.4,zb-0.01]) cuboid([11.9,4.2,6.01], anchor=BOT);
}

include <robotics.scad>
// Fingertip wedge (+X finger, open pose). World-frame XZ from the drawing.
$fn = 32;
module xz(h) rotate([90,0,0]) linear_extrude(h, center=true) children();
xo = 75.5;          // outer face (151/2)
xp = xo - 21.9 + 4.8; // pad back face: mount is 21.9 incl. 4.8 pad -> 58.4
difference(){
  xz(26) polygon([[xp,80.3],[xo,80.3],[xo,81.2],[60,116.3],[xp,116.3]]);
  // 3x M3 bolt holes per top view: rows 3 mm and 3+10 mm from outer edge, +-7 in Y
  for (p=[[xo-3,7],[xo-3,-7],[xo-13,0]]) translate([p[0],p[1],75]) cylinder(d=3.2, h=50);
}

include <robotics.scad>
// Grip pad, 20 mm tall (drawing), inner face at X = 75.5 - 21.9 = 53.6
translate([56.0,0,106.3]) cuboid([4.8,26,20], rounding=0.8);

